package compose

import (
	crmcontracts "github.com/margince/margince/backend/internal/contracts"
	"github.com/margince/margince/backend/internal/shared/kernel/langcopy"
)

var reportingDefinitionWords = map[crmcontracts.ReportingMetricID]langcopy.Phrase{
	reportingBookingsWon:              {En: "Won deals in the selected close interval, using their current valid closing and frozen base value. Results follow the current deal owner, including after reassignment. Saved editions retain the owner and values captured then.", De: "Die im gewählten Abschlusszeitraum gewonnenen Deals mit ihrem aktuellen gültigen Abschluss und dem festgehaltenen Basiswert. Ergebnisse folgen der aktuell verantwortlichen Person, auch nach einer Neuzuweisung. Gespeicherte Ausgaben behalten die damals erfasste Zuordnung und Werte.", Vi: "Các deal thắng trong khoảng thời gian chốt đã chọn, dùng lần chốt hợp lệ hiện tại và giá trị cơ sở đã lưu. Kết quả theo người chịu trách nhiệm hiện tại, kể cả sau khi chuyển giao. Bản báo cáo đã lưu giữ nguyên người chịu trách nhiệm và giá trị tại thời điểm ghi nhận."},
	reportingClosedWinRate:            {En: "Won ÷ (won + lost) × 100 in the same current closing cohort, scoped to the current deal owner. Reopened deals no longer count. Suppressed when fewer than five outcomes or when contributions are withheld.", De: "Gewonnen ÷ (gewonnen + verloren) × 100 für dieselbe aktuelle Abschlussgruppe, zugeordnet zur aktuell verantwortlichen Person. Wiedereröffnete Deals zählen nicht mehr. Bei weniger als fünf Ergebnissen oder zurückgehaltenen Beiträgen wird kein Wert angezeigt.", Vi: "Thắng ÷ (thắng + thua) × 100 trong cùng tập lần chốt hiện tại, theo người chịu trách nhiệm deal hiện tại. Deal mở lại không còn được tính. Không hiển thị khi có ít hơn năm kết quả hoặc có khoản đóng góp bị ẩn."},
	reportingOpenPipeline:             {En: "Open deals now, valued in the reporting base currency, with a separate expected-close window. A past event interval does not reconstruct past pipeline.", De: "Aktuell offene Deals, bewertet in der Basiswährung des Berichts, mit einem eigenen Zeitraum für den erwarteten Abschluss. Ein vergangener Ereigniszeitraum rekonstruiert keine historische Pipeline.", Vi: "Các deal hiện đang mở, được định giá theo đồng tiền cơ sở của báo cáo, với khoảng thời gian chốt dự kiến riêng. Khoảng thời gian sự kiện trong quá khứ không tái dựng pipeline quá khứ."},
	reportingStageAge:                 {En: "Median and 75th percentile of completed days since latest entry into each open deal's current stage. Creation date is the fallback when no entry history exists. At least five observations are required.", De: "Median und 75. Perzentil der vollständigen Tage seit dem letzten Eintritt jedes offenen Deals in seine aktuelle Phase. Ohne Phasenhistorie gilt das Erstellungsdatum. Mindestens fünf Beobachtungen sind erforderlich.", Vi: "Trung vị và phân vị thứ 75 của số ngày trọn vẹn kể từ lần gần nhất mỗi deal đang mở vào giai đoạn hiện tại. Dùng ngày tạo nếu không có lịch sử chuyển giai đoạn. Cần ít nhất năm quan sát."},
	reportingQualifiedPipelineCreated: {En: "The first non-reversed entry into a stage configured as qualified at the transition. Credit and valuation belong to that event. Later regression and re-entry do not create additional qualified pipeline.", De: "Der erste nicht rückgängig gemachte Eintritt in eine zum Übergangszeitpunkt als qualifiziert konfigurierte Phase. Zuordnung und Bewertung gehören zu diesem Ereignis. Ein späterer Rückschritt und erneuter Eintritt erzeugen keine weitere qualifizierte Pipeline.", Vi: "Lần đầu vào một giai đoạn được cấu hình là đủ điều kiện tại thời điểm chuyển, không bị đảo ngược. Ghi nhận đóng góp và định giá thuộc về sự kiện đó. Việc lùi rồi vào lại giai đoạn không tạo thêm pipeline đủ điều kiện."},
	reportingMeetingsHeld:             {En: "Distinct eligible customer meetings scheduled in the interval and confirmed held by capture time. Recorded held transitions retain their host and customer eligibility. Older meetings without attribution history use their current host and customer links, with partial coverage. Future and unresolved meetings do not count.", De: "Eindeutige geeignete Kundentermine, die im Zeitraum geplant und bis zur Erfassung als durchgeführt bestätigt wurden. Erfasste Übergänge behalten Gastgeber und Kundeneignung. Ältere Termine ohne Zuordnungshistorie verwenden den aktuellen Gastgeber und Kundenbezug mit teilweiser Abdeckung. Zukünftige und ungeklärte Termine zählen nicht.", Vi: "Các cuộc họp khách hàng đủ điều kiện riêng biệt, được lên lịch trong khoảng thời gian và xác nhận đã diễn ra trước lúc ghi nhận. Lịch sử xác nhận đã diễn ra giữ nguyên người chủ trì và điều kiện khách hàng. Cuộc họp cũ không có lịch sử quy trách nhiệm dùng người chủ trì và liên kết khách hàng hiện tại, với độ bao phủ một phần. Không tính cuộc họp tương lai hoặc chưa xác định."},
	reportingAcceptedOpportunities:    {En: "Distinct opportunities first credited through an accepted handoff in the interval. The first acceptance wins across repeated submissions. Credit remains with the originating SDR after transfer; restricted source details remain hidden.", De: "Eindeutige Verkaufschancen, die im Zeitraum erstmals durch eine akzeptierte Übergabe zugeordnet wurden. Bei wiederholten Einreichungen zählt die erste Annahme. Die Zuordnung bleibt nach einer Übertragung beim ursprünglichen SDR; zugriffsbeschränkte Quelldetails bleiben verborgen.", Vi: "Các cơ hội riêng biệt được ghi nhận lần đầu qua bàn giao được chấp nhận trong khoảng thời gian. Lần chấp nhận đầu tiên được tính dù gửi lại nhiều lần. Đóng góp vẫn thuộc SDR ban đầu sau khi chuyển giao; chi tiết nguồn bị hạn chế truy cập vẫn được ẩn."},
	reportingForecastLanding:          {En: "The existing forecast landing for this fiscal quarter and supported scope. Won plus supported open is evidence-based landing; the manager call is a whole-period replacement, never another additive segment.", De: "Das bestehende erwartete Ergebnis für dieses Geschäftsquartal und den unterstützten Bereich. Gewonnene und belegte offene Deals ergeben das evidenzbasierte Ergebnis. Die Einschätzung der Führungskraft ersetzt den gesamten Zeitraum und wird nicht als weiterer Betrag addiert.", Vi: "Kết quả dự báo hiện có cho quý tài chính này và phạm vi được hỗ trợ. Deal thắng cộng deal mở có bằng chứng tạo thành kết quả dựa trên bằng chứng; nhận định của quản lý thay thế kết quả cả kỳ, không phải một phần cộng thêm."},
}
